<script lang="ts">
  import '../app.css';
  import '../design.css';
  import { onMount } from 'svelte';
  import { page } from '$app/state';
  import { provideDemo } from '#lib/demo.svelte';
  import Cart from '#lib/components/Cart.svelte';
  let { children } = $props();
  const demo = provideDemo();
  let menu = $state(false);
  let query = $state('');
  let subscribed = $state(false);
  let email = $state('');
  function modal(node: HTMLDialogElement) { node.showModal(); return { destroy() { node.close(); } }; }
  const nav = [{ path: '/proyectos', es: 'Proyectos', en: 'Projects' }, { path: '/productos', es: 'Productos', en: 'Products' }, { path: '/como-se-hace', es: 'Cómo se hace', en: 'How it works' }, { path: '/tienda', es: 'Tienda', en: 'Shop' }];
  onMount(() => demo.init());
  $effect(() => { JSON.stringify(demo.state); demo.persist(); if (typeof document !== 'undefined') document.documentElement.lang = demo.state.language; });
  $effect(() => { page.url.pathname; menu = false; demo.drawer = false; });
</script>
<svelte:head><title>WEPRO · {demo.t('Prototipo local', 'Local prototype')}</title><meta name="description" content="WEPRO — prototipo local autónomo con datos de demostración" /></svelte:head>
<a href="#main" class="skip">{demo.t('Saltar al contenido', 'Skip to content')}</a>
<div class="topbar"><span>{demo.t('DEMO LOCAL · Todos los datos e importes son de muestra', 'LOCAL DEMO · All data and amounts are samples')}</span><a href="/tiendas">{demo.t('Tiendas físicas', 'Physical stores')}</a><select aria-label={demo.t('Idioma', 'Language')} value={demo.state.language} onchange={(e) => demo.language(e.currentTarget.value as 'es' | 'en')}><option value="es">ES · EUR €</option><option value="en">EN · EUR €</option></select></div>
<header><div class="header-inner"><a href="/" class="logo" aria-label="WEPRO · Home">WEPRO<span>®</span></a><button class="menu-button secondary" aria-expanded={menu} onclick={() => menu = !menu}>{menu ? demo.t('Cerrar', 'Close') : demo.t('Menú', 'Menu')}</button><nav aria-label={demo.t('Navegación principal', 'Main navigation')} class:open={menu}>{#each nav as n}<a class:active={page.url.pathname.startsWith(n.path)} href={n.path}>{demo.t(n.es, n.en)}</a>{/each}</nav><form class="search" action="/productos"><input name="q" bind:value={query} aria-label={demo.t('Buscar producto o RAL', 'Search product or RAL')} placeholder={demo.t('Busca producto o RAL', 'Search product or RAL')}/><button class="text-button" aria-label={demo.t('Buscar', 'Search')}>⌕</button></form><a class="icon-link" href="/favoritos" aria-label={demo.t('Favoritos', 'Wishlist')}>♡</a><button class="cart-toggle secondary" onclick={() => demo.drawer = true}>{demo.t('Carrito', 'Cart')} <span class="badge">{demo.state.cart.reduce((n, l) => n + l.quantity, 0)}</span></button></div></header>
<main id="main" data-ready={demo.ready}>{@render children()}</main>
<footer><div class="container"><div class="newsletter"><div><h2>{demo.t('Ideas para tu próximo proyecto.', 'Ideas for your next project.')}</h2><p>{demo.t('Suscripción de demostración. No enviamos emails.', 'Demo subscription. We do not send emails.')}</p></div><form class="row" onsubmit={(e) => { e.preventDefault(); subscribed = true; }}><label class="grow">Email<input type="email" required bind:value={email} placeholder="demo@example.com"/></label><button>{demo.t('Suscribirme', 'Subscribe')}</button></form></div>{#if subscribed}<p role="status">{demo.t('Suscripción simulada guardada en esta pantalla.', 'Simulated subscription saved on this screen.')}</p>{/if}<div class="footer-grid"><div><a class="logo" href="/">WEPRO</a><p>{demo.t('Hazlo tú. Hazlo fácil. Hazlo WEPRO.', 'Do it yourself. Make it easy. Make it WEPRO.')}</p><small>{demo.t('Prototipo de demostración de Recíproco.', 'Demo prototype by Recíproco.')}</small></div><div><h3>{demo.t('Comprar', 'Shop')}</h3><a href="/proyectos">{demo.t('Por proyecto', 'By project')}</a><a href="/productos#familias">{demo.t('Por fase', 'By phase')}</a><a href="/tienda#kits">{demo.t('Packs y kits', 'Packs and kits')}</a><a href="/productos?collection=offers">{demo.t('Ofertas demo', 'Demo offers')}</a></div><div><h3>{demo.t('Aprende', 'Learn')}</h3><a href="/como-se-hace">{demo.t('Recomendador', 'Recommender')}</a><a href="/como-se-hace#biblioteca">{demo.t('Tutoriales y vídeos', 'Tutorials and videos')}</a><a href="/guia">{demo.t('Guía imprimible', 'Printable guide')}</a><a href="/como-se-hace#faq">FAQ</a></div><div><h3>{demo.t('Ayuda', 'Help')}</h3><a href="/ayuda#envios">{demo.t('Envíos y devoluciones', 'Shipping and returns')}</a><a href="/pedidos">{demo.t('Estado de mi pedido', 'Order status')}</a><a href="/tiendas">{demo.t('Localizador demo', 'Demo store locator')}</a><a href="/ayuda#contacto">{demo.t('Contacto', 'Contact')}</a></div></div><div class="footer-bottom"><span>{demo.t('Sin pagos reales · Sin servicios externos', 'No real payments · No external services')}</span><a href="/ayuda#legal">{demo.t('Aviso legal · Privacidad · Cookies', 'Legal · Privacy · Cookies')}</a><button class="text-button" onclick={() => { demo.reset(); subscribed = false; email = ''; }}>{demo.t('Reiniciar demo', 'Reset demo')}</button></div></div></footer>
<div class="toast" role="status" aria-live="polite">{demo.notice}{#if demo.notice}<button class="text-button" aria-label={demo.t('Cerrar aviso', 'Close notice')} onclick={() => demo.notice = ''}>×</button>{/if}</div>
{#if demo.drawer}<dialog use:modal class="cart-dialog" aria-label={demo.t('Carrito de demostración', 'Demo cart')} oncancel={() => demo.drawer = false}><div class="row between"><a href="/carrito" onclick={() => demo.drawer = false}>{demo.t('Abrir carrito completo', 'Open full cart')}</a><button class="secondary" onclick={() => demo.drawer = false}>{demo.t('Cerrar', 'Close')} ×</button></div><Cart /></dialog>{/if}
